"""Tests for weekly_update.py. Run: python3 -m unittest discover -s .github/maintenance"""

import os
import unittest
from datetime import date, datetime, timezone

os.environ.setdefault("GITHUB_REPOSITORY", "owner/repo")
import weekly_update as w  # noqa: E402


def at(text):
    return datetime.fromisoformat(text).replace(tzinfo=timezone.utc)


class Schedule(unittest.TestCase):
    def test_daylight_saving_keeps_the_21_utc_run(self):
        # Friday 2026-10-30: Chicago is on CDT (UTC-5), so 21:00 UTC is 4:00 PM.
        start, end = w.scheduled_window("0 21 * * 5", at("2026-10-30T21:00:00"))
        self.assertEqual(end.isoformat(), "2026-10-30T16:00:00-05:00")
        self.assertEqual(start.isoformat(), "2026-10-23T16:00:00-05:00")
        self.assertIsNone(w.scheduled_window("0 22 * * 5", at("2026-10-30T22:00:00")))

    def test_standard_time_keeps_the_22_utc_run(self):
        # Friday 2026-11-06: DST ended Nov 1, Chicago is on CST (UTC-6).
        self.assertIsNone(w.scheduled_window("0 21 * * 5", at("2026-11-06T21:00:00")))
        start, end = w.scheduled_window("0 22 * * 5", at("2026-11-06T22:00:00"))
        self.assertEqual(end.isoformat(), "2026-11-06T16:00:00-06:00")
        # The week spans the switch: it starts at 4:00 PM CDT the previous Friday.
        self.assertEqual(start.isoformat(), "2026-10-30T16:00:00-05:00")

    def test_spring_forward(self):
        # DST starts 2026-03-08; Friday 2026-03-13 is CDT again.
        start, end = w.scheduled_window("0 21 * * 5", at("2026-03-13T21:00:00"))
        self.assertEqual(start.isoformat(), "2026-03-06T16:00:00-06:00")
        self.assertEqual(end.isoformat(), "2026-03-13T16:00:00-05:00")

    def test_late_run_reports_the_same_week(self):
        # GitHub can start scheduled jobs late; 3 hours late is still Friday in Chicago.
        _, end = w.scheduled_window("0 21 * * 5", at("2026-10-31T00:30:00"))
        self.assertEqual(end.isoformat(), "2026-10-30T16:00:00-05:00")

    def test_boundaries(self):
        start, end = w.scheduled_window("0 21 * * 5", at("2026-10-30T21:00:00"))
        self.assertFalse(w.in_window("2026-10-23T21:00:00Z", start, end))  # 4:00 PM last week
        self.assertTrue(w.in_window("2026-10-23T21:01:00Z", start, end))   # 4:01 PM last week
        self.assertTrue(w.in_window("2026-10-30T21:00:00Z", start, end))   # 4:00 PM this week
        self.assertFalse(w.in_window("2026-10-30T21:00:01Z", start, end))


class Manual(unittest.TestCase):
    def test_whole_days_in_chicago(self):
        start, end = w.manual_window(date(2026, 10, 19), date(2026, 10, 23))
        self.assertTrue(w.in_window("2026-10-19T05:00:00Z", start, end))   # 00:00 CDT
        self.assertFalse(w.in_window("2026-10-19T04:59:59Z", start, end))
        self.assertTrue(w.in_window("2026-10-24T04:59:59Z", start, end))   # 23:59:59 CDT
        self.assertFalse(w.in_window("2026-10-24T05:00:00Z", start, end))

    def test_title(self):
        title, _ = w.render(*w.manual_window(date(2026, 10, 19), date(2026, 10, 23)), [], [], [])
        self.assertEqual(title, "Weekly update: Oct 19 to Oct 23, 2026")
        title, body = w.render(*w.scheduled_window("0 21 * * 5", at("2026-10-30T21:00:00")),
                               [], [], [])
        self.assertEqual(title, "Weekly update: Oct 23 to Oct 30, 2026")
        self.assertIn("Fri Oct 23, 2026 4:01 PM CDT to Fri Oct 30, 2026 4:00 PM CDT", body)


class Summary(unittest.TestCase):
    def test_stops_at_tested(self):
        body = "The check now runs on Linux.\nIt was stuck.\n\n**Tested:** all passed."
        self.assertEqual(w.summary(body), "The check now runs on Linux. It was stuck.")

    def test_inline_tested_after_one_paragraph(self):
        self.assertEqual(w.summary("Docs only.\n**Tested:** nothing"), "Docs only.")

    def test_footer_and_empty(self):
        self.assertEqual(w.summary("Adds a page.\n---\n_Generated by x_"), "Adds a page.")
        self.assertEqual(w.summary(None), "(no description)")


if __name__ == "__main__":
    unittest.main()
